// Generated by chart-to-tla.mjs from watch.mmd. Reader states are the chart's own states.
export const regions = ["lifecycle", "subscription"];
const LABELS: Record<string, string> = {
  Watch: "Watch",
  RepeatWatch: "Repeat watch",
  Pause: "Pause",
  Resume: "Resume",
  ReplacePolicy: "Replace policy",
  ReplacePausedPolicy: "Replace paused policy",
  Remove: "Remove",
};

// The actions the reader takes. facts.settled needs them. Add cause() and detail() as the spec grows.
export const readerActions: string[] = [];
export const state = (v: Record<string, string>) => regions.map((r) => v[r]).join(" | ");
export const step = (action: string) => LABELS[action] ?? action;
